export const STORAGE_KEY = 'htwkr-theme-v1';
export const fields = [
 ['background','全站背景','网页与 3D 画布的黑色底'],
 ['text','主要文字','标题、献词、顶部标志'],
 ['muted','次要文字','说明、署名和资源分类'],
 ['accent','强调色','链接和编辑入口文字'],
 ['surface','按钮底色','打开书本、编辑入口'],
 ['onSurface','按钮文字','按钮上的文字和图标'],
 ['border','按钮边框','按钮轮廓'],
];
const palette=(name,description,values)=>({name,description,colors:Object.fromEntries(fields.map((f,i)=>[f[0],values[i]]))});
export const presets=[
 palette('原版黑色','保留剧场式的黑色背景。',['#000000','#ffffff','#8c8c8c','#ffffff','#000000','#ffffff','#ffffff']),
 palette('奶油纸 · 灰紫','推荐：温柔、像纸质作品集，适合现在的粉彩书页。',['#f3eee5','#39323f','#6f6573','#705781','#e7ddec','#493951','#b4a3be']),
 palette('浅鼠尾草','自然、安静，让人物和作品图片更突出。',['#e7ede5','#293e35','#56685c','#426b58','#d3e0d4','#293e35','#8ca58f']),
 palette('雾蓝 · 墨色','清爽、理性，更偏工具与产品作品集。',['#e8eef5','#28394e','#596a80','#365d8c','#d4e0ef','#28394e','#97abc4']),
 palette('午夜灰紫','保留深色氛围，降低纯黑的生硬感。',['#25212d','#f5eff9','#bcb0c9','#d5b9ed','#44394f','#f5eff9','#83728f']),
];
export function validateTheme(value){
 if(value?.version!==1 || typeof value.name!=='string' || value.name.length>60 || !value.colors) throw new Error('需要版本 1 的配色 JSON 配置。');
 const colors={};
 for(const [key] of fields){if(!/^#[\da-f]{6}$/i.test(value.colors[key]))throw new Error('颜色必须是完整的 #RRGGBB 格式。');colors[key]=value.colors[key].toLowerCase();}
 const pageBrightness=value.pageBrightness===undefined?1:value.pageBrightness;
 if(typeof pageBrightness!=='number'||!Number.isFinite(pageBrightness)||pageBrightness<0.7||pageBrightness>1.6)throw new Error('书页亮度须为 0.7 到 1.6 之间的数字。');
 return {version:1,name:value.name,colors,pageBrightness};
}
export function readTheme(){try{return validateTheme(JSON.parse(localStorage.getItem(STORAGE_KEY)));}catch{return {version:1,name:presets[3].name,colors:{...presets[3].colors},pageBrightness:1};}}
export function contrast(a,b){const lum=c=>{const v=c.slice(1).match(/../g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return v[0]*.2126+v[1]*.7152+v[2]*.0722;};const x=lum(a),y=lum(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
